I'll analyze this NASTRAN quadrilateral plate bending element routine and translate it to C++17 with Eigen.

Let me start by understanding the key algorithm:
1. KQDPLT computes the 4x4 subtriangle decomposition of a quad plate
2. For each of 4 subtriangles (excluding the "not" one), it calls KTRBSC to get 3x3 K matrices
3. It assembles them into a 12x12 stiffness matrix

Let me write the complete implementation.

```cpp
#include <Eigen/Dense>
#include <iostream>
#include <cmath>
#include <vector>
#include <iomanip>

using namespace Eigen;
using namespace std;

// Material properties (isotropic plate)
struct Material {
    double E, nu, t;
    double G11, G12, G13, G22, G23, G33;
    double I; // moment of inertia = t^3/12
};

// Compute G matrix for isotropic material (bending)
// G = D matrix (flexural rigidity related)
void computeG(Material& mat) {
    double E = mat.E, nu = mat.nu;
    // For plate bending, G matrix relates moments to curvatures
    // G = E/(1-nu^2) * [[1, nu, 0],[nu,1,0],[0,0,(1-nu)/2]]
    double factor = E / (1.0 - nu*nu);
    mat.G11 = factor * 1.0;
    mat.G12 = factor * nu;
    mat.G13 = 0.0;
    mat.G22 = factor * 1.0;
    mat.G23 = 0.0;
    mat.G33 = factor * (1.0 - nu) / 2.0;
}

// KTRBSC: Basic bending triangle
// Returns 9 3x3 matrices (K^U) stored in a 9x9 arrangement
// Inputs: coordinates of triangle (x1,y1),(x2,y2),(x3,y3) in element system
// Output: K matrices (3x3 each) for the 9 combinations
// We'll return a 9x9 matrix where block (i,j) is 3x3
MatrixXd KTRBSC(const Material& mat,
                double x1, double y1,
                double x2, double y2,
                double x3, double y3,
                double sinth, double costh) {
    // Build E matrix (3x3) with I, J, K vectors
    // I-vector = R2 - R1
    double e11 = x2 - x1;
    double e14 = y2 - y1;
    double e17 = 0.0;
    double xsubb = sqrt(e11*e11 + e14*e14 + e17*e17);
    e11 /= xsubb; e14 /= xsubb; e17 /= xsubb;

    // R3 - R1
    double e2 = x3 - x1;
    double e5 = y3 - y1;
    double e8 = 0.0;

    double xsubc = e11*e2 + e14*e5 + e17*e8;

    // K-vector = I cross (R3-R1)
    double e1 = e14*e8 - e5*e17;
    double e4 = e2*e17 - e11*e8;
    double e7 = e11*e5 - e2*e14;
    double ysubc = sqrt(e1*e1 + e4*e4 + e7*e7);
    e1 /= ysubc; e4 /= ysubc; e7 /= ysubc;

    // J = K cross I
    double e12 = e4*e17 - e14*e7;
    double e15 = e11*e7 - e1*e17;
    double e18 = e1*e14 - e11*e4;
    double temp = sqrt(e12*e12 + e15*e15 + e18*e18);
    e12 /= temp; e15 /= temp; e18 /= temp;

    // G matrix (3x3)
    Matrix3d G;
    G << mat.G11, mat.G12, mat.G13,
         mat.G12, mat.G22, mat.G23,
         mat.G13, mat.G23, mat.G33;

    // D = G * I (I = moment of inertia)
    Matrix3d D = G * mat.I;

    double area = xsubb * ysubc / 2.0;
    double xbar = (xsubb + xsubc) / 3.0;
    double ybar = ysubc / 3.0;

    double xcsq = xsubc*xsubc;
    double ycsq = ysubc*ysubc;
    double xbsq = xsubb*xsubb;
    double xcyc = xsubc*ysubc;
    double px2 = (xbsq + xsubb*xsubc + xcsq) / 6.0;
    double py2 = ycsq / 6.0;
    double pxy2 = ysubc*(xsubb + 2.0*xsubc) / 12.0;
    double xbar3 = 3.0*xbar;
    double ybar3 = 3.0*ybar;
    double ybar2 = 2.0*ybar;

    // K^X matrix (6x6) stored in A(1..36)
    MatrixXd A = MatrixXd::Zero(9, 9); // will hold K^U blocks
    MatrixXd KX = MatrixXd::Zero(6, 6);

    double d1 = D(0,0), d2 = D(0,1), d3 = D(0,2);
    double d5 = D(1,1), d6 = D(1,2), d9 = D(2,2);

    KX(0,0) = d1;
    KX(0,1) = d3;
    KX(0,2) = d2;
    KX(0,3) = d1*xbar3;
    KX(0,4) = d2*xbar + ybar2*d3;
    KX(0,5) = d2*ybar3;
    KX(1,0) = d3;
    KX(1,1) = d9;
    KX(1,2) = d6;
    KX(1,3) = d3*xbar3;
    KX(1,4) = d6*xbar + ybar2*d9;
    KX(1,5) = d6*ybar3;
    KX(2,0) = d2;
    KX(2,1) = d6;
    KX(2,2) = d5;
    KX(2,3) = d2*xbar3;
    KX(2,4) = d5*xbar + ybar2*d6;
    KX(2,5) = d5*ybar3;
    KX(3,0) = d1*xbar3;
    KX(3,1) = d3*xbar3;
    KX(3,2) = d2*xbar3;
    KX(3,3) = d1*9.0*px2;
    KX(3,4) = d2*3.0*px2 + 6.0*pxy2*d3;
    KX(3,5) = d2*9.0*pxy2;
    KX(4,0) = d2*xbar + ybar2*d3;
    KX(4,1) = d6*xbar + ybar2*d9;
    KX(4,2) = d5*xbar + ybar2*d6;
    KX(4,3) = d2*3.0*px2 + 6.0*pxy2*d3;
    KX(4,4) = d5*px2 + 4.0*pxy2*d6 + 4.0*py2*d9;
    KX(4,5) = d5*3.0*pxy2 + 6.0*py2*d6;
    KX(5,0) = d2*ybar3;
    KX(5,1) = d6*ybar3;
    KX(5,2) = d5*ybar3;
    KX(5,3) = d2*9.0*pxy2;
    KX(5,4) = d5*3.0*pxy2 + 6.0*py2*d6;
    KX(5,5) = d5*9.0*py2;

    double temp4 = 4.0*area;
    KX *= temp4;

    // HBAR matrix (6x6) stored at A(37..72)
    MatrixXd HB = MatrixXd::Zero(6, 6);
    HB(0,0) = xbsq;
    HB(0,3) = xbsq*xsubb;
    HB(1,1) = xsubb;
    HB(2,0) = -2.0*xsubb;
    HB(2,3) = -3.0*xbsq;
    HB(3,3) = xcsq;
    HB(3,4) = xcyc;
    HB(3,5) = ycsq;
    HB(4,3) = xcsq*xsubc;
    HB(4,4) = ycsq*xsubc;
    HB(4,5) = ycsq*ysubc;
    HB(5,1) = xsubc;
    HB(5,2) = ysubc*2.0;
    HB(5,3) = xcyc*2.0;
    HB(5,4) = ycsq*3.0;
    HB(5,5) = -2.0*xsubc;
    // Wait, need to recheck indices. Let me redo carefully.
    // A(37)=XBSQ -> HB(0,0)
    // A(40)=XBSQ*XSUBB -> HB(0,3)
    // A(44)=XSUBB -> HB(1,1)
    // A(49)=-2*XSUBB -> HB(2,0)
    // A(52)=-3*XBSQ -> HB(2,3)
    // A(55)=XCSQ -> HB(3,3)
    // A(56)=XCYC -> HB(3,4)
    // A(57)=YCSQ -> HB(3,5)
    // A(58)=XCSQ*XSUBC -> HB(4,3)
    // A(59)=YCSQ*XSUBC -> HB(4,4)
    // A(60)=YCSQ*YSUBC -> HB(4,5)
    // A(62)=XSUBC -> HB(5,1)
    // A(63)=YSUBC*2 -> HB(5,2)
    // A(65)=XCYC*2 -> HB(5,3)
    // A(66)=YCSQ*3 -> HB(5,4)
    // A(67)=-2*XSUBC -> HB(5,5)
    // A(68)=-YSUBC -> HB(6,1) -- but HB is 6x6, index 6 invalid!
    // Hmm, A(68) is row 7 (1-indexed) = index 6. That's out of 6x6.
    // Actually HBAR is 6x6 stored at A(37..72), so A(37..72) = 36 elements.
    // A(68) = 68-37 = 31 -> row 31/6 = 5, col 31%6 = 1 -> HB(5,1)
    // Let me recompute: A(37) is HB(0,0). A(37+k) is HB(k/6, k%6).
    // A(68): k=31, row=5, col=1 -> HB(5,1)
    // A(70): k=33, row=5, col=3 -> HB(5,3)
    // A(71): k=34, row=5, col=4 -> HB(5,4)

    // Let me redo HB properly
    HB.setZero();
    HB(0,0) = xbsq;              // A37
    HB(0,3) = xbsq*xsubb;        // A40
    HB(1,1) = xsubb;             // A44
    HB(2,0) = -2.0*xsubb;        // A49
    HB(2,3) = -3.0*xbsq;         // A52
    HB(3,3) = xcsq;              // A55
    HB(3,4) = xcyc;              // A56
    HB(3,5) = ycsq;              // A57
    HB(4,3) = xcsq*xsubc;        // A58
    HB(4,4) = ycsq*xsubc;        // A59
    HB(4,5) = ycsq*ysubc;        // A60
    HB(5,1) = xsubc;             // A62
    HB(5,2) = ysubc*2.0;         // A63
    HB(5,3) = xcyc*2.0;          // A65
    HB(5,4) = ycsq*3.0;          // A66
    HB(5,5) = -2.0*xsubc;        // A67
    // A(68)=-YSUBC -> k=31, row=5,col=1 -> HB(5,1) += -ysubc? 
    // Wait A(62) already set HB(5,1)=xsubc. A(68) also HB(5,1). 
    // Hmm, that means A(62) and A(68) both map to HB(5,1)? 
    // A(62): k=25, row=4, col=1 -> HB(4,1)!
    // Let me recompute: 62-37=25, 25/6=4, 25%6=1 -> HB(4,1)
    // 63-37=26, 26/6=4, 26%6=2 -> HB(4,2)
    // 65-37=28, 28/6=4, 28%6=4 -> HB(4,4)
    // 66-37=29, 29/6=4, 29%6=5 -> HB(4,5)
    // 67-37=30, 30/6=5, 30%6=0 -> HB(5,0)
    // 68-37=31, 31/6=5, 31%6=1 -> HB(5,1)
    // 70-37=33, 33/6=5, 33%6=3 -> HB(5,3)
    // 71-37=34, 34/6=5, 34%6=4 -> HB(5,4)

    HB.setZero();
    HB(0,0) = xbsq;              // A37
    HB(0,3) = xbsq*xsubb;        // A40
    HB(1,1) = xsubb;             // A44
    HB(2,0) = -2.0*xsubb;        // A49
    HB(2,3) = -3.0*xbsq;         // A52
    HB(3,3) = xcsq;              // A55
    HB(3,4) = xcyc;              // A56
    HB(3,5) = ycsq;              // A57
    HB(4,3) = xcsq*xsubc;        // A58
    HB(4,4) = ycsq*xsubc;        // A59
    HB(4,5) = ycsq*ysubc;        // A60
    HB(4,1) = xsubc;             // A62
    HB(4,2) = ysubc*2.0;         // A63
    HB(4,4) += xcyc*2.0;         // A65 -- wait A65 is HB(4,4)? 
    // 65-37=28, 28/6=4, 28%6=4 -> HB(4,4). But A59 already set HB(4,4)=ycsq*xsubc.
    // Hmm, that's a conflict. Let me recheck the Fortran.

    // Actually looking again: A(65) = XCYC*2.0. 65-37=28 -> row 4, col 4. 
    // But A(59)=YCSQ*XSUBC also row 4 col 4. That can't be right.
    // Let me recount. A(37) through A(72) is 36 elements = 6x6.
    // A(37)=idx0, A(38)=1, ..., A(72)=35.
    // A(55)=18 -> row3 col0. A(56)=19 -> row3 col1. A(57)=20 -> row3 col2.
    // A(58)=21 -> row3 col3. A(59)=22 -> row3 col4. A(60)=23 -> row3 col5.
    // A(62)=25 -> row4 col1. A(63)=26 -> row4 col2.
    // A(65)=28 -> row4 col4. A(66)=29 -> row4 col5.
    // A(67)=30 -> row5 col0. A(68)=31 -> row5 col1.
    // A(70)=33 -> row5 col3. A(71)=34 -> row5 col4.

    // So HB(3,3)=xcsq, HB(3,4)=xcyc, HB(3,5)=ycsq
    // HB(4,3)=xcsq*xsubc, HB(4,4)=ycsq*xsubc, HB(4,5)=ycsq*ysubc
    // HB(4,1)=xsubc, HB(4,2)=ysubc*2, HB(4,4)=xcyc*2 (overwrites? no, +=)
    // Actually in Fortran these are separate assignments, so A(65) overwrites A(59).
    // Wait no - A(59) and A(65) are different array positions! A(59) != A(65).
    // A(59) is index 22, A(65) is index 28. Different positions.
    // So HB(3,4) = A(59) = ycsq*xsubc, and HB(4,4) = A(65) = xcyc*2.

    HB.setZero();
    HB(0,0) = xbsq;              // A37
    HB(0,3) = xbsq*xsubb;        // A40
    HB(1,1) = xsubb;             // A44
    HB(2,0) = -2.0*xsubb;        // A49
    HB(2,3) = -3.0*xbsq;         // A52
    HB(3,3) = xcsq;              // A55
    HB(3,4) = xcyc;              // A56
    HB(3,5) = ycsq;              // A57
    HB(3,3) = xcsq*xsubc;        // A58 -- wait A58=21 -> row3 col3
    // A(58)=21 -> row3 col3. So HB(3,3) = xcsq*xsubc (overwrites A55)
    // Hmm but A55=18 -> row3 col0. Let me redo.
    // 55-37=18, 18/6=3, 18%6=0 -> HB(3,0)
    // 56-37=19 -> HB(3,1)
    // 57-37=20 -> HB(3,2)
    // 58-37=21 -> HB(3,3)
    // 59-37=22 -> HB(3,4)
    // 60-37=23 -> HB(3,5)

    HB.setZero();
    HB(0,0) = xbsq;              // A37
    HB(0,3) = xbsq*xsubb;        // A40
    HB(1,1) = xsubb;             // A44
    HB(2,0) = -2.0*xsubb;        // A49
    HB(2,3) = -3.0*xbsq;         // A52
    HB(3,0) = xcsq;              // A55
    HB(3,1) = xcyc;              // A56
    HB(3,2) = ycsq;              // A57
    HB(3,3) = xcsq*xsubc;        // A58
    HB(3,4) = ycsq*xsubc;        // A59
    HB(3,5) = ycsq*ysubc;        // A60
    HB(4,1) = xsubc;             // A62
    HB(4,2) = ysubc*2.0;         // A63
    HB(4,4) = xcyc*2.0;          // A65
    HB(4,5) = ycsq*3.0;          // A66
    HB(5,0) = -2.0*xsubc;        // A67
    HB(5,1) = -ysubc;            // A68
    HB(5,3) = -3.0*xcsq;         // A70
    HB(5,4) = -ycsq;             // A71

    // T2 = 0 for our case, so skip the T2 block

    // Invert HB
    MatrixXd HBinv = HB.inverse();

    // K^Q = KX * HBinv (6x6)
    MatrixXd KQ = KX * HBinv;

    // K^II = HBinv^T * KQ (6x6)
    MatrixXd KII = HBinv.transpose() * KQ;

    // S matrix (6x3)
    MatrixXd S = MatrixXd::Zero(6, 3);
    S(0,0) = 1.0; S(0,1) = 0.0; S(0,2) = -xsubb;
    S(1,0) = 0.0; S(1,1) = 1.0; S(1,2) = 0.0;
    S(2,0) = 0.0; S(2,1) = 0.0; S(2,2) = 1.0;
    S(3,0) = 1.0; S(3,1) = ysubc; S(3,2) = -xsubc;
    S(4,0) = 0.0; S(4,1) = 1.0; S(4,2) = 0.0;
    S(5,0) = 0.0; S(5,1) = 0.0; S(5,2) = 1.0;

    // KIA = KII * S (6x3)
    MatrixXd KIA = KII * S;

    // KAA = S^T * KIA (3x3)
    MatrixXd KAA = S.transpose() * KIA;

    // KIA = -KIA
    KIA = -KIA;

    // Now arrange 9 3x3 matrices of K^U
    // K^U is 9x9, blocks (i,j) for i,j in 0..2
    // From Fortran:
    // A(1..9) = KAA (3x3) -> block (0,0)
    // A(10..18) = KIA arranged -> blocks (0,1),(0,2),(1,0),(1,1),(1,2),(2,0),(2,1),(2,2)
    // A(37..81) = KII arranged -> blocks (1,1)...(2,2)

    // Let me carefully map. The 9x9 K^U has blocks:
    // Row block 0: KAA (3x3), KIA^T (3x3), KIA^T (3x3)
    // Actually from the Fortran arrangement:
    // A(1..9) = KAA
    // A(10..18) = KIA^T (transposed)
    // A(19..27) = KIA^T
    // A(28..36) = KIA
    // A(37..45) = KII block (0,0)
    // A(46..54) = KII block (0,1)
    // A(55..63) = KII block (0,2)
    // A(64..72) = KII block (1,0)
    // A(73..81) = KII block (1,1)
    // A(82..90) = KII block (1,2) -- wait, only 81 elements

    // Hmm, K^U is 9x9 = 81 elements. Let me re-read.
    // "ARRANGE NINE 3X3 MATRICES OF K SUPER U"
    // A(28..36) = A(46..54)  (shift)
    // A(10..18) = KIA^T
    // A(19..27) = KIA^T
    // A(37..81) = KII blocks

    // Actually the 9x9 K^U is:
    // [ KAA    KIA^T   KIA^T ]
    // [ KIA    KII00   KII01 ]
    // [ KIA    KII10   KII11 ]
    // where KII is 6x6 split into 4 3x3 blocks.

    MatrixXd KU = MatrixXd::Zero(9, 9);
    KU.block<3,3>(0,0) = KAA;
    KU.block<3,3>(0,3) = KIA.transpose();
    KU.block<3,3>(0,6) = KIA.transpose();
    KU.block<3,3>(3,0) = KIA;
    KU.block<3,3>(6,0) = KIA;
    KU.block<3,3>(3,3) = KII.block<3,3>(0,0);
    KU.block<3,3>(3,6) = KII.block<3,3>(0,3);
    KU.block<3,3>(6,3) = KII.block<3,3>(3,0);
    KU.block<3,3>(6,6) = KII.block<3,3>(3,3);

    return KU;
}

int main() {
    // Test case
    Material mat;
    mat.E = 200e9;
    mat.nu = 0.3;
    mat.t = 0.01;
    mat.I = mat.t*mat.t*mat.t / 12.0;
    computeG(mat);

    // Quad vertices
    double xA=0, yA=0;
    double xB=1, yB=0;
    double xC=1, yC=1;
    double xD=0, yD=1;

    // Pivot point: choose node 1 (A). NPVT = 1.
    int NPIVOT = 1; // 1-indexed
    int JNOT;
    if (NPIVOT - 2 <= 0) JNOT = NPIVOT + 2;
    else JNOT = NPIVOT - 2;
    // NPIVOT=1 -> JNOT=3

    // M matrix: mapping of triangles
    // M = {2,4,1, 3,1,2, 4,2,3, 1,3,4}
    int M[12] = {2,4,1, 3,1,2, 4,2,3, 1,3,4};

    // Coordinates in element system (R matrix 2x4)
    // R(1,i) = x, R(2,i) = y for point i
    // For a flat quad in xy plane, we can use the actual coords
    // But the Fortran computes R from I,J,K vectors.
    // For our flat quad, I = x-axis, J = y-axis, K = z-axis.
    // R(1,1)=0, R(2,1)=0 (point A is origin)
    // R(1,2)=1, R(2,2)=0 (point B)
    // R(1,3)=1, R(2,3)=1 (point C)
    // R(1,4)=0, R(2,4)=1 (point D)

    // Let's compute R properly using the algorithm
    // VQ1 = A, VQ2 = B, VQ3 = C, VQ4 = D
    double VQ1[3] = {xA, yA, 0};
    double VQ2[3] = {xB, yB, 0};
    double VQ3[3] = {xC, yC, 0};
    double VQ4[3] = {xD, yD, 0};

    double D1[3], D2[3], A1[3];
    for (int i=0;i<3;i++) {
        D1[i] = VQ3[i] - VQ1[i];
        D2[i] = VQ4[i] - VQ2[i];
        A1[i] = VQ2[i] - VQ1[i];
    }

    // K = D1 cross D2
    double KV[3];
    KV[0] = D1[1]*D2[2] - D2[1]*D1[2];
    KV[1] = D1[2]*D2[0] - D2[2]*D1[0];
    KV[2] = D1[0]*D2[1] - D2[0]*D1[1];
    double temp = sqrt(KV[0]*KV[0]+KV[1]*KV[1]+KV[2]*KV[2]);
    for (int i=0;i<3;i++) KV[i] /= temp;

    // H = (A1 . K)/2
    temp = (A1[0]*KV[0]+A1[1]*KV[1]+A1[2]*KV[2])/2.0;

    // I = A1 - H*K
    double IV[3];
    for (int i=0;i<3;i++) IV[i] = A1[i] - temp*KV[i];
    temp = sqrt(IV[0]*IV[0]+IV[1]*IV[1]+IV[2]*IV[2]);
    for (int i=0;i<3;i++) IV[i] /= temp;

    // J = K cross I
    double JV[3];
    JV[0] = KV[1]*IV[2] - IV[1]*KV[2];
    JV[1] = KV[2]*IV[0] - IV[2]*KV[0];
    JV[2] = KV[0]*IV[1] - IV[1]*KV[0];
    temp = sqrt(JV[0]*JV[0]+JV[1]*JV[1]+JV[2]*JV[2]);
    for (int i=0;i<3;i++) JV[i] /= temp;

    // R matrix
    double R[2][4];
    R[0][0] = 0; R[1][0] = 0;
